                b.style.cssText = 'font-size:13px;color:var(--text-sec);margin:0 0 12px;line-height:1.7;';
                b.innerHTML = '你的专属后缀：<b style="color:var(--primary);">/' + escHtml(u.suffix || '') + '/</b>　节点 ' + (u.nodeCount || 0) + ' / ' + (u.maxNodes || 0);
